package com.zad.almoslem;
import android.Manifest;import android.app.Activity;import android.content.pm.PackageManager;import android.os.Build;import java.util.Calendar;import android.content.Intent;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.os.Bundle;import android.os.Handler;import android.os.Looper;import android.view.Gravity;import android.view.View;import android.widget.*;
import java.util.Locale;
public class HomeActivity extends Activity{
String[] prayers={"الفجر","الظهر","العصر","المغرب","العشاء"};TextView[] times=new TextView[5];TextView sunriseTime;LinearLayout prayerHero;Handler visualHandler=new Handler(Looper.getMainLooper());Runnable visualTicker=new Runnable(){public void run(){refreshAdhanVisual();visualHandler.postDelayed(this,1000);}};int dp(float n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}
GradientDrawable shape(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(r));return d;}
TextView label(String s,int z,int c,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);t.setGravity(Gravity.CENTER);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}
void open(Class<?> c){startActivity(new Intent(this,c));}
@Override public void onCreate(Bundle b){super.onCreate(b);try{AppThemeColors.apply(this);}catch(Exception e){android.util.Log.e("ZadStartup","Theme initialization failed",e);}try{ReminderReceiver.ensureDefaultDailyReminders(this);}catch(Exception e){android.util.Log.e("ZadStartup","Default reminder setup failed",e);}try{RemoteAudioAssets.refresh(this);}catch(Exception e){android.util.Log.w("ZadStartup","Remote audio sync could not start",e);}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},2401);try{build();}catch(Exception e){android.util.Log.e("ZadStartup","Home screen initialization failed",e);showStartupFallback(e);}if(Build.VERSION.SDK_INT<33||checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)==PackageManager.PERMISSION_GRANTED)new Handler(Looper.getMainLooper()).postDelayed(this::promptFullScreenAdhanPermission,650);}
void promptFullScreenAdhanPermission(){
if(Build.VERSION.SDK_INT<34)return;
android.app.NotificationManager manager=(android.app.NotificationManager)getSystemService(NOTIFICATION_SERVICE);
if(manager==null||manager.canUseFullScreenIntent())return;
android.content.SharedPreferences p=getSharedPreferences("zad_reminders",MODE_PRIVATE);
if(p.getBoolean("full_screen_permission_prompted",false))return;
p.edit().putBoolean("full_screen_permission_prompted",true).apply();
new android.app.AlertDialog.Builder(this)
.setTitle("إظهار الأذان على شاشة الهاتف")
.setMessage("حتى تظهر خلفية الأذان كاملة على شاشة الهاتف عند قفل الجهاز، اسمح لزاد المسلم بإشعارات الشاشة الكاملة من إعدادات الهاتف.")
.setPositiveButton("فتح الإعدادات",(dialog,which)->{
try{startActivity(new Intent(android.provider.Settings.ACTION_MANAGE_APP_USE_FULL_SCREEN_INTENT,android.net.Uri.parse("package:"+getPackageName())));}
catch(Exception error){android.util.Log.e("ZadStartup","Could not open full-screen notification settings",error);}
})
.setNegativeButton("لاحقًا",null).show();
}
void showStartupFallback(Exception error){LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setGravity(Gravity.CENTER);root.setPadding(dp(24),dp(24),dp(24),dp(24));root.setBackgroundColor(Color.rgb(244,247,243));TextView title=label("زاد وطمأنينة",25,Color.rgb(8,48,40),true);TextView message=label("حدث تعذر أثناء تحميل بعض مكونات التطبيق.",15,Color.rgb(65,80,70),false);TextView details=label((error==null?"سبب غير محدد":error.getClass().getSimpleName()+": "+String.valueOf(error.getMessage())),13,Color.rgb(120,45,35),false);details.setTextIsSelectable(true);Button retry=new Button(this);retry.setText("إعادة المحاولة");retry.setOnClickListener(v->{try{build();}catch(Exception e){android.util.Log.e("ZadStartup","Retry failed",e);showStartupFallback(e);}});root.addView(title);root.addView(message);root.addView(details);root.addView(retry);setContentView(root);}
void build(){ScrollView scroll=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(14),dp(14),dp(14),dp(22));root.setBackgroundColor(AppThemeColors.bg(this));scroll.addView(root);
TextView heading=label("زاد وطمأنينة",25,Color.WHITE,true);TextView ayah=label("﴿ أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ ﴾",14,Color.rgb(232,211,158),true);TextView ref=label("سورة الرعد • الآية ٢٨",11,Color.rgb(222,239,229),false);TextClock clock=new TextClock(this);clock.setFormat12Hour("hh:mm a");clock.setFormat24Hour("HH:mm");clock.setTextSize(27);clock.setTextColor(Color.WHITE);clock.setGravity(Gravity.CENTER);clock.setTypeface(Typeface.DEFAULT,Typeface.BOLD);
LinearLayout hero=new LinearLayout(this);prayerHero=hero;hero.setOrientation(1);hero.setGravity(Gravity.CENTER);hero.setPadding(dp(14),dp(14),dp(14),dp(14));hero.setBackground(shape(AppThemeColors.primary(this),20));hero.addView(heading);hero.addView(clock);hero.addView(ayah);hero.addView(ref);root.addView(hero,new LinearLayout.LayoutParams(-1,-2));
TextView prayerTitle=label("مواقيت الصلاة",19,AppThemeColors.text(this),true);prayerTitle.setGravity(Gravity.RIGHT);prayerTitle.setPadding(0,dp(16),0,dp(8));root.addView(prayerTitle);
LinearLayout prayerCard=new LinearLayout(this);prayerCard.setOrientation(0);prayerCard.setPadding(dp(7),dp(12),dp(7),dp(12));prayerCard.setBackground(shape(AppThemeColors.surface(this),16));
for(int i=0;i<prayers.length;i++){LinearLayout cell=new LinearLayout(this);cell.setOrientation(1);cell.setGravity(Gravity.CENTER);cell.addView(label(new String[]{"🌅","☀️","🌤️","🌇","🌙"}[i],17,Color.rgb(25,90,70),false));cell.addView(label(prayers[i],11,AppThemeColors.muted(this),true));times[i]=label("--:--",13,AppThemeColors.text(this),true);cell.addView(times[i]);prayerCard.addView(cell,new LinearLayout.LayoutParams(0,-2,1));}LinearLayout sunriseCell=new LinearLayout(this);sunriseCell.setOrientation(1);sunriseCell.setGravity(Gravity.CENTER);sunriseCell.addView(label("🌄",17,Color.rgb(25,90,70),false));sunriseCell.addView(label("الشروق",11,AppThemeColors.muted(this),true));sunriseTime=label("--:--",13,AppThemeColors.text(this),true);sunriseCell.addView(sunriseTime);prayerCard.addView(sunriseCell,new LinearLayout.LayoutParams(0,-2,1));root.addView(prayerCard);
android.content.SharedPreferences timePrefs=getSharedPreferences("zad_reminders",MODE_PRIVATE);
RadioGroup timeFormat=new RadioGroup(this);timeFormat.setOrientation(RadioGroup.HORIZONTAL);timeFormat.setGravity(Gravity.CENTER);RadioButton h24=new RadioButton(this);h24.setText("24 ساعة");h24.setId(View.generateViewId());RadioButton h12=new RadioButton(this);h12.setText("12 ساعة");h12.setId(View.generateViewId());timeFormat.addView(h24);timeFormat.addView(h12);timeFormat.check(timePrefs.getBoolean("prayer_time_format_24",true)?h24.getId():h12.getId());timeFormat.setOnCheckedChangeListener((g,id)->{timePrefs.edit().putBoolean("prayer_time_format_24",id==h24.getId()).apply();refreshTimes();});root.addView(timeFormat,new LinearLayout.LayoutParams(-1,-2));
Button details=new Button(this);details.setText("عرض مواقيت الصلاة بالتفصيل");details.setOnClickListener(v->open(PrayerDashboardActivity.class));root.addView(details,new LinearLayout.LayoutParams(-1,-2));
TextView quick=label("تصفّح عبادتك",18,AppThemeColors.text(this),true);quick.setGravity(Gravity.RIGHT);quick.setPadding(0,dp(14),0,dp(5));root.addView(quick);
addShortcut(root,"📖 المصحف الشريف",MushafPageActivity.class);addShortcut(root,"🎧 استماع القرآن الكريم",QuranListeningActivity.class);addShortcut(root,"📻 إذاعة القرآن الكريم",RadioActivity.class);addShortcut(root,"۞ السبحة الإلكترونية",TasbeehActivity.class);addShortcut(root,"🎞️ ريلز إسلامي",IslamicReelsActivity.class);
setContentView(AppTabs.wrap(this,scroll,"home"));refreshTimes();}
void addShortcut(LinearLayout root,String title,Class<?> c){
LinearLayout card=new LinearLayout(this);card.setOrientation(0);card.setGravity(Gravity.CENTER_VERTICAL);card.setPadding(dp(15),dp(12),dp(15),dp(12));
GradientDrawable bg=shape(AppThemeColors.surface(this),16);bg.setStroke(dp(1),Color.rgb(218,205,173));card.setBackground(bg);
TextView icon=label(title.substring(0,2),20,Color.rgb(185,146,75),true);card.addView(icon,new LinearLayout.LayoutParams(dp(42),dp(42)));
LinearLayout details=new LinearLayout(this);details.setOrientation(1);details.setGravity(Gravity.CENTER_VERTICAL);
TextView name=label(title,15,AppThemeColors.text(this),true);name.setGravity(Gravity.RIGHT);details.addView(name);
TextView hint=label("افتح القسم وتابع من حيث توقفت",11,AppThemeColors.muted(this),false);hint.setGravity(Gravity.RIGHT);details.addView(hint);
LinearLayout.LayoutParams detailLp=new LinearLayout.LayoutParams(0,-2,1f);detailLp.setMargins(dp(10),0,dp(8),0);card.addView(details,detailLp);
TextView arrow=label("‹",26,AppThemeColors.primary(this),true);card.addView(arrow,new LinearLayout.LayoutParams(dp(24),-2));
card.setOnClickListener(v->open(c));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(9);root.addView(card,lp);
}
void refreshTimes(){android.content.SharedPreferences p=getSharedPreferences("zad_reminders",MODE_PRIVATE);for(int i=0;i<prayers.length;i++){int h=p.getInt("native_time_hour_"+prayers[i],-1),m=p.getInt("native_time_minute_"+prayers[i],0);boolean use24=p.getBoolean("prayer_time_format_24",true);if(h<0)times[i].setText("--:--");else if(use24)times[i].setText(String.format(Locale.getDefault(),"%02d:%02d",h,m));else{int dh=h%12;if(dh==0)dh=12;times[i].setText(String.format(Locale.getDefault(),"%d:%02d %s",dh,m,h<12?"ص":"م"));}}int sh=p.getInt("native_sunrise_hour",-1),sm=p.getInt("native_sunrise_minute",0);if(sunriseTime!=null){if(sh<0)sunriseTime.setText("--:--");else if(p.getBoolean("prayer_time_format_24",true))sunriseTime.setText(String.format(Locale.getDefault(),"%02d:%02d",sh,sm));else{int dh=sh%12;if(dh==0)dh=12;sunriseTime.setText(String.format(Locale.getDefault(),"%d:%02d %s",dh,sm,sh<12?"ص":"م"));}}refreshAdhanVisual();}
void refreshAdhanVisual(){
if(prayerHero==null)return;
android.content.SharedPreferences p=getSharedPreferences("zad_reminders",MODE_PRIVATE);
boolean show=p.getBoolean("adhan_active",false);long now=System.currentTimeMillis();
for(String prayer:prayers){int h=p.getInt("native_time_hour_"+prayer,-1);if(h<0)continue;Calendar c=Calendar.getInstance();c.set(Calendar.HOUR_OF_DAY,h);c.set(Calendar.MINUTE,p.getInt("native_time_minute_"+prayer,0));c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);long delta=now-c.getTimeInMillis();if(delta>=0&&delta<15L*60L*1000L)show=true;}
if(show)prayerHero.setBackgroundResource(R.drawable.azhar_mosque_bg);else prayerHero.setBackground(shape(AppThemeColors.primary(this),20));
}
@Override protected void onResume(){super.onResume();if(times[0]!=null)refreshTimes();visualHandler.removeCallbacks(visualTicker);visualHandler.post(visualTicker);android.content.SharedPreferences p=getSharedPreferences("zad_reminders",MODE_PRIVATE);for(String prayer:prayers){int h=p.getInt("native_time_hour_"+prayer,-1);if(h>=0&&p.getBoolean("prayer_enabled_"+prayer,true)){Calendar next=Calendar.getInstance();next.set(Calendar.HOUR_OF_DAY,h);next.set(Calendar.MINUTE,p.getInt("native_time_minute_"+prayer,0));next.set(Calendar.SECOND,0);next.set(Calendar.MILLISECOND,0);if(next.getTimeInMillis()<=System.currentTimeMillis())next.add(Calendar.DAY_OF_YEAR,1);ReminderReceiver.schedulePrayer(this,prayer,next.getTimeInMillis());} } RamadanReminderReceiver.scheduleAll(this); }
@Override protected void onPause(){visualHandler.removeCallbacks(visualTicker);super.onPause();}
}